void OnCommand(HWND, Win*, WORD code, HWND child, WORD) override {
 if (!child) return;
 auto* sink = SinkForHwnd(child);
 if (!sink) return;

 OSEvent e; e.key = (int)code;
 switch (code) {
 case BN_CLICKED:
 e.type = OSEvent::Command;
 sink->OnOSEvent(e);
 break;
 case CBN_SELCHANGE:
 case EN_CHANGE:
 e.type = OSEvent::Change;
 sink->OnOSEvent(e);
 break;
 }
}
